CREATE OR REPLACE FUNCTION public.age_gain(p_liquid text, p_age double precision, p_cellar boolean)
 RETURNS double precision
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
begin
  if not coalesce(brew_ages(p_liquid), false) or p_age is null or not (p_age > 0) then return 0; end if;
